import jax
import jax.numpy as jnp

def solve(initial, target, rate, tolerance, limit):
    def body(_, carry):
        state, steps = carry
        running = (steps < limit) & ~(jnp.abs(target - state) <= tolerance)
        return jax.lax.cond(
            running,
            lambda _: (state + rate * (target - state), steps + 1),
            lambda _: (state, steps),
            operand=None,
        )

    # Static bounds support reverse mode; skipped iterations preserve the carry.
    return jax.lax.fori_loop(0, 16, body, (initial, jnp.int32(0)))

