import jax
import jax.numpy as jnp

def solve(initial, target, rate, tolerance, limit):
    def cond(carry):
        state, steps = carry
        return ((steps < limit) & (steps < 16) & (jnp.abs(target-state) > tolerance))
    def body(carry):
        state, steps = carry
        return state + rate * (target-state), steps + 1
    # A static bound permits reverse-mode differentiation, while cond keeps
    # the stopping decision (including limit) dynamic under JIT.
    def bounded_body(_, carry):
        return jax.lax.cond(cond(carry), body, lambda value: value, carry)

    return jax.lax.fori_loop(
        0, 16, bounded_body, (initial, jnp.int32(0))
    )

